<?php
namespace Tests\Feature;
use Tests\TestCase;use Tests\Concerns\MarketingEditingFixtures;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{Queue,Http,Storage};use Illuminate\Support\Str;use App\Models\{User,MarketingAiRun,MarketingVideoFilm};use App\Services\Marketing\{MarketingOptimization,MarketingOptimizationClient};
class MarketingOptimizationTest extends TestCase {
 use RefreshDatabase,MarketingEditingFixtures;
 private function setupSource():array{$rows=$this->editingFilm();$this->actingAs(User::findOrFail($rows[0]->owner_id));return $rows;}
 public function test_start_reuses_existing_completed_check_without_explicit_recheck():void {
  Queue::fake();[$p,$f]=$this->setupSource();$url=route('marketing.workspace.optimization.start',[$p->id,$f->id]);
  $first=$this->postJson($url,['request_id'=>(string)Str::uuid(),'base_hash'=>$f->output_sha256])->assertOk()->json('run.id');
  MarketingAiRun::findOrFail($first)->update(['status'=>'completed']);
  $this->postJson($url,['request_id'=>(string)Str::uuid(),'base_hash'=>$f->output_sha256])->assertOk()->assertJsonPath('run.id',$first);
  Queue::assertPushed(\App\Jobs\ProcessMarketingOptimization::class,1);$this->assertSame(1,MarketingAiRun::where('action',MarketingOptimization::ACTION)->count());Http::assertNothingSent();
 }
 public function test_start_is_source_bound_idempotent_and_does_not_make_a_film():void {Queue::fake();[$p,$f]=$this->setupSource();$count=MarketingVideoFilm::count();$body=['request_id'=>(string)Str::uuid(),'base_hash'=>$f->output_sha256];$url=route('marketing.workspace.optimization.start',[$p->id,$f->id]);$r=$this->postJson($url,$body)->assertOk();$this->assertSame('gpt-5.6-sol',$r->json('run.model'));$this->postJson($url,$body)->assertOk()->assertJsonPath('run.id',$r->json('run.id'));$this->assertSame($count,MarketingVideoFilm::count());Queue::assertPushed(\App\Jobs\ProcessMarketingOptimization::class,1);Http::assertNothingSent();}
 public function test_foreign_owner_cannot_read_or_start():void {Queue::fake();[$p,$f]=$this->setupSource();$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));$this->getJson(route('marketing.workspace.optimization.show',[$p->id,$f->id]))->assertNotFound();$this->postJson(route('marketing.workspace.optimization.start',[$p->id,$f->id]),['request_id'=>(string)Str::uuid(),'base_hash'=>$f->output_sha256])->assertNotFound();}
 public function test_adoption_cannot_select_unknown_or_unavailable_suggestions():void {Queue::fake();[$p,$f]=$this->setupSource();$r=MarketingAiRun::create(['project_id'=>$p->id,'request_id'=>(string)Str::uuid(),'action'=>MarketingOptimization::ACTION,'status'=>'completed','usage'=>['owner_id'=>$p->owner_id,'film_id'=>$f->id,'base_hash'=>$f->output_sha256,'recipe_digest'=>\App\Services\Marketing\MarketingEditingDigest::hash($f->input),'stage'=>'completed','model'=>MarketingOptimizationClient::MODEL,'answer'=>['recommendations'=>[]]]]);$this->postJson(route('marketing.workspace.optimization.adopt',[$p->id,$f->id]),['run_id'=>$r->id,'request_id'=>(string)Str::uuid(),'selected'=>['invented'],'consent'=>true])->assertUnprocessable();}
 public function test_source_hash_changes_are_rejected_before_enqueue():void {Queue::fake();[$p,$f]=$this->setupSource();$this->postJson(route('marketing.workspace.optimization.start',[$p->id,$f->id]),['request_id'=>(string)Str::uuid(),'base_hash'=>str_repeat('0',64)])->assertConflict();Queue::assertNotPushed(\App\Jobs\ProcessMarketingOptimization::class);}
 public function test_adoption_only_passes_selected_changes_and_replays_without_a_second_render():void {
  Queue::fake();[$p,$f]=$this->setupSource();$state=app(\App\Services\Marketing\MarketingOptimizationPlan::class)->baseline($f);$state['settings']['volume']=36;
  $plan=$this->partialMock(\App\Services\Marketing\MarketingOptimizationPlan::class);$plan->shouldReceive('baseline')->andReturn($state);$plan->shouldReceive('validateState')->andReturnUsing(fn($s)=>$s);
  $recs=[['id'=>'music-down','capability'=>'music','target_id'=>'music','scene_number'=>0,'action'=>'adjust','patch'=>['volume'=>18],'selectable'=>true,'needs_speech_optin'=>false],['id'=>'remove-outro','capability'=>'outro','target_id'=>'outro','scene_number'=>0,'action'=>'remove','patch'=>[],'selectable'=>true,'needs_speech_optin'=>false]];
  $r=MarketingAiRun::create(['project_id'=>$p->id,'request_id'=>(string)Str::uuid(),'action'=>MarketingOptimization::ACTION,'status'=>'completed','usage'=>['owner_id'=>$p->owner_id,'film_id'=>$f->id,'base_hash'=>$f->output_sha256,'recipe_digest'=>\App\Services\Marketing\MarketingEditingDigest::hash($f->input),'stage'=>'completed','model'=>MarketingOptimizationClient::MODEL,'answer'=>['recommendations'=>$recs]]]);
  $this->partialMock(\App\Services\Marketing\MarketingFilmPackaging::class)->shouldReceive('prepare')->once()->withArgs(function(...$args)use($state){$this->assertSame(18,$args[5]['volume']);$this->assertSame($state['settings']['enabled'],$args[5]['enabled']);$this->assertSame($state['information_cards'],$args[7]);$this->assertSame($state['speed'],$args[11]);return true;})->andReturn($f);
  $request=(string)Str::uuid();$service=app(MarketingOptimization::class);$this->assertSame($f->id,$service->adopt($r,$request,['music-down'])->id);$this->assertSame($f->id,$service->adopt($r->fresh(),$request,['music-down'])->id);$this->assertSame(['music-down'],$r->fresh()->usage['adoptions'][$request]['selected']);Http::assertNothingSent();
 }
}
